function returnedOrigin(){let s=fixture();s.route=[s.actual,'1,0',s.actual];for(let n=0;n<2;n++){const prepared=S.prepareJump(s,()=>({dice:[3,3,3,3,3,3],total:18}));s=S.transition(prepared.state,n?'Jump: Destination → Origin':'Jump: Origin → Destination',next=>S.commitJump(next,{attemptId:prepared.attempt.id,elapsed:166}));}assert.equal(s.actual,'0,0');assert.equal(S.jumpUndoEligibility(s).allowed,true);return s;}
for(const delayed of [false,true])test(`board: ${delayed?'split':'native'} commit permanently closes last jump mulligan; preview/cancel never do`,async()=>{
 const before=returnedOrigin(),h=setup(before),original=setup(before,originalHarness);const raw=h.bytes();prepare(h,'board');same(h.persisted(),before);assert.equal(S.jumpUndoEligibility(h.api.state).allowed,true);assert.equal(h.counters.writes,0);h.api.closeModal();assert.equal(h.bytes(),raw);assert.equal(S.jumpUndoEligibility(h.api.state).allowed,true);prepare(h,'board');prepare(original,'board');await original.submit();const gate=delayed?serviceSaveGate(h.store):null,operation=h.submit();if(gate){assert.equal(S.jumpUndoEligibility(h.persisted()).allowed,true);gate.entries[0].write();assert.equal(S.jumpUndoEligibility(h.persisted()).allowed,false);gate.entries[0].fulfill();}await operation;gate?.restore();same(canonical(h.persisted()),canonical(original.persisted()));assert.equal(S.jumpUndoEligibility(h.persisted()).allowed,false);assert.equal(h.persisted().jumpAttempts.at(-1).closed,true);const loaded=fresh(h.persisted()),expected=fresh(original.persisted(),originalHarness);await loaded.runAction('undo');await expected.runAction('undo');same(canonical(loaded.persisted()),canonical(expected.persisted()));assert.equal(S.jumpUndoEligibility(loaded.persisted()).allowed,false);assert.equal(loaded.persisted().jumpAttempts.at(-1).closed,true);assert.equal(loaded.api.passengers.testSnapshot().drafts.length,0);
});
for(const phase of ['preview cancel','known-unsaved final','unknown final'])test(`board: ${phase} never consumes saved eligible jump mulligan`,async()=>{
 const h=setup(returnedOrigin()),raw=h.bytes();prepare(h,'board');if(phase==='preview cancel')h.api.closeModal();else{const gate=serviceSaveGate(h.store),operation=h.submit();if(phase==='known-unsaved final'){h.failNext();gate.entries[0].fulfill();}else gate.entries[0].reject();await operation;gate.restore();}assert.equal(h.bytes(),raw);assert.equal(S.jumpUndoEligibility(h.persisted()).allowed,true);assert.equal(h.counters.writes,0);
});

for(const phase of ['first durable read','handoff durable read'])test(`board: transient ${phase} failure followed by verified baseline permits only deliberate fresh preview`,async()=>{
 const h=setup();firstForm(h);const read=h.store.read,raw=h.bytes(),first=h.api.modalSession;let reads=0,reentrant=0,attempt;
 h.store.read=function(){reads++;if(reads===(phase==='first durable read'?1:2))throw Error('Transient independent durable read unavailable');return read.call(this);};
 trap(h,'modal-error','textContent',value=>{if(/Transient independent/.test(value)&&!reentrant++){attempt=h.submit();}});
 await h.submit();await attempt;assert.equal(h.bytes(),raw);assert.equal(h.counters.writes,0);assert.equal(h.api.modalSession,first);assert.match(ui(h).modalTitle,/^Board/);assert.match(ui(h).modalError,/Transient independent/);assert.equal(ui(h).submitDisabled,false);assert.equal(h.store.reloadRequired??false,false);assert.ok(reads>=2,'Failure recovery independently verified exact readable durable baseline');const previews=h.calls.previews?.length||0;
 await h.submit();assert.equal(ui(h).modalTitle,'Confirm passenger booking');assert.equal(h.bytes(),raw);assert.equal(h.counters.writes,0);assert.equal(h.calls.previews.length,previews+1);await h.submit();assert.equal(h.counters.writes,1);assert.equal(ui(h).modalOpen,false);
});
for(const outcome of ['same-revision different data','unreadable saved baseline'])test(`board: durable ${outcome} present before entry never grants confirmation authority`,async()=>{
 const h=setup(),original=h.persisted();if(outcome==='same-revision different data'){const disk=h.persisted();disk.bank='7654321';h.external(disk,{publish:false});}else h.store.read=()=>{throw Error('Independent saved baseline unavailable');};const raw=h.bytes();firstForm(h);await h.submit();assert.equal(h.bytes(),raw);assert.equal(h.counters.writes,0);same(h.api.state,original);assert.match(ui(h).modalTitle,/^Board/);assert.equal(ui(h).submitDisabled,true);assert.equal(h.store.reloadRequired,true);assert.equal(h.calls.previews?.length||0,0);await h.submit();assert.equal(h.bytes(),raw);
});

for(const kind of kinds)for(const drift of ['capacity','hours','accepted source identity'])test(`${kind}: same-revision ${drift} while provider is pending before publication cannot report stale success`,async t=>{
 const {h,gate,operation}=await pending(t,{kind});if(drift==='capacity')h.api.state.ship.accommodation.passengerCapacity.reservedCabins++;else if(drift==='hours')h.api.state.hours++;else if(kind==='board'){const e=P.latestPassengerSearch(h.api.state),i=e.offers.findIndex(o=>o.passageClass==='high');e.offers[i]=structuredClone(e.offers[i]);}else{const c=h.api.state.contracts.find(c=>c.kind==='passenger'),i=h.api.state.contracts.indexOf(c);h.api.state.contracts[i]=structuredClone(c);}gate.entries[0].fulfill();await operation;assert.equal(h.counters.writes,1,'Already accepted provider writes exactly its prepared candidate');same(h.persisted(),gate.entries[0].args[0]);noSuccess(h);assert.equal(ui(h).submitDisabled,true);const raw=h.bytes();await h.submit();assert.equal(h.bytes(),raw);assert.equal(gate.entries.length,1);
});
for(const kind of kinds)for(const fault of ['saved drift warning throw','saved drift warning Notes','rejection after stale publication'])test(`${kind}: ${fault} preserves genuine provenance and terminal/newer-dialog authority`,async t=>{
 const {h,gate,operation,detached}=await pending(t,{kind});h.api.state.hours++;let fired=0,newerBody,newerHandler;
 if(fault!=='rejection after stale publication')trap(h,'modal-error','textContent',value=>{if(!/earlier review changed/.test(value)||fired++)return;if(fault==='saved drift warning throw')throw Error('Synthetic stale-saved warning failure');h.dom.ids.get('modal').close();h.dom.ids.get('modal').dispatch('close');h.dom.ids.get('notes').onclick();newerBody=body(h);newerHandler=h.dom.ids.get('modal-form').onsubmit;h.dom.ids.get('modal-error').textContent='Genuine newer Notes warning';});
 if(fault==='rejection after stale publication'){gate.entries[0].write();gate.entries[0].reject(new SaveNotCommittedError(Error('Contradictory rejection after genuine saved drift')));}else gate.entries[0].fulfill();await operation;assert.equal(h.counters.writes,1);same(h.persisted(),gate.entries[0].args[0]);noSuccess(h);
 if(fault==='saved drift warning Notes'){assert.equal(fired,1);assert.equal(ui(h).modalTitle,'Rules & Notes');assert.equal(body(h),newerBody);assert.equal(h.dom.ids.get('modal-form').onsubmit,newerHandler);assert.equal(ui(h).modalError,'Genuine newer Notes warning');assert.equal(h.store.reloadRequired??false,false);}else {terminal(h);assert.match(ui(h).message,/saved, but/);}
 const raw=h.bytes();await detached(submitEvent(h));await h.submit();assert.equal(h.bytes(),raw);assert.equal(gate.entries.length,1);if(newerHandler)assert.equal(h.dom.ids.get('modal-form').onsubmit,newerHandler);
});

for(const mode of ['deferred','retry','unknown','cancel'])test('manual passenger terms use retained preview and save ownership: '+mode,async t=>{
 const h=setup(),before=h.bytes(),search=h.api.state.latestPassengerSearchId;
 h.api.passengers.manual('1,0');h.fill({destination:'1,0',passageClass:'high',count:'2',fare:'1234',cabinMode:'shared',serviceConfirmed:true,reason:'Synthetic referee terms'});await h.submit();
 assert.equal(ui(h).modalTitle,'Confirm manual passenger booking');assert.equal(ui(h).modalError,'');assert.equal(h.bytes(),before);
 if(mode==='cancel'){const detached=h.dom.ids.get('modal-form').onsubmit;h.api.closeModal();await detached(submitEvent(h));assert.equal(h.bytes(),before);assert.equal(h.counters.writes,0);return;}
 const gate=serviceSaveGate(h.store);t.after(()=>gate.restore());const detached=h.dom.ids.get('modal-form').onsubmit,operation=h.submit();await flush();assert.equal(gate.entries.length,1);await h.submit();await detached(submitEvent(h));assert.equal(gate.entries.length,1);assert.equal(h.bytes(),before);assert.equal(ui(h).modalOpen,true);
 if(mode==='unknown'){gate.entries[0].reject();await operation;terminal(h);assert.equal(h.bytes(),before);return;}
 if(mode==='retry'){
  const accepted=structuredClone(gate.entries[0].args[0]);gate.entries[0].reject(new SaveNotCommittedError(Error('Synthetic known unwritten manual booking')));await operation;assert.equal(h.bytes(),before);assert.equal(ui(h).submitDisabled,false);
  const retry=h.submit();await flush();assert.equal(gate.entries.length,2);same(canonical(gate.entries[1].args[0].contracts),canonical(accepted.contracts));same(canonical(gate.entries[1].args[0].events),canonical(accepted.events));gate.entries[1].fulfill();await retry;
 }else{gate.entries[0].fulfill();await operation;}
 assert.equal(h.counters.writes,1);assert.equal(h.persisted().contracts.at(-1).payment,'2468');assert.equal(h.persisted().latestPassengerSearchId,search);assert.equal(ui(h).modalOpen,false);assert.equal(h.persisted().bank,JSON.parse(before).bank);assert.equal(h.api.passengers.testSnapshot().drafts.length,4);
});
